-- ==========================================================
-- NESRU MICHAEL WEB APP v2 - SUPABASE SQL SCHEMA
-- Shared Feed (Like, Comment, Share), Follow/Friends, Live Chat + Online Presence
-- ==========================================================

-- 1. Profiles Table (Fayyadamtoota & Online Status)
create table if not exists public.profiles (
  email text primary key,
  full_name text not null,
  bio text default '',
  last_seen timestamp with time zone default timezone('utc'::text, now()),
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 2. Posts Table (Barreeffama Waliinii)
create table if not exists public.posts (
  id bigint generated by default as identity primary key,
  title text not null,
  body text not null,
  author text not null,
  author_email text not null,
  image_url text,
  shares_count int default 0,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- Ensure columns exist if table was created earlier
alter table public.posts add column if not exists author_email text;
alter table public.posts add column if not exists shares_count int default 0;

-- 3. Post Likes Table
create table if not exists public.post_likes (
  id bigint generated by default as identity primary key,
  post_id bigint references public.posts(id) on delete cascade not null,
  user_email text not null,
  created_at timestamp with time zone default timezone('utc'::text, now()),
  unique(post_id, user_email)
);

-- 4. Post Comments Table
create table if not exists public.post_comments (
  id bigint generated by default as identity primary key,
  post_id bigint references public.posts(id) on delete cascade not null,
  author_name text not null,
  author_email text not null,
  comment_text text not null,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 5. Follows & Friend Requests Table
create table if not exists public.relationships (
  id bigint generated by default as identity primary key,
  sender_email text not null,
  receiver_email text not null,
  rel_type text not null check (rel_type in ('follow', 'friend')),
  status text not null default 'accepted' check (status in ('pending', 'accepted')),
  created_at timestamp with time zone default timezone('utc'::text, now()),
  unique(sender_email, receiver_email, rel_type)
);

-- 6. Messages Table (Live Chat)
create table if not exists public.messages (
  id bigint generated by default as identity primary key,
  sender_name text not null,
  sender_email text not null,
  receiver_email text, -- null = Chat Waliinii (Group), email = Chat Dhuunfaa (DM)
  message_text text not null,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- Enable Row Level Security
alter table public.profiles enable row level security;
alter table public.posts enable row level security;
alter table public.post_likes enable row level security;
alter table public.post_comments enable row level security;
alter table public.relationships enable row level security;
alter table public.messages enable row level security;

-- Open Policies for App Users
do $$
declare
  tbl text;
begin
  foreach tbl in array array['profiles','posts','post_likes','post_comments','relationships','messages']
  loop
    execute format('drop policy if exists "Allow all select on %I" on public.%I', tbl, tbl);
    execute format('create policy "Allow all select on %I" on public.%I for select using (true)', tbl, tbl);

    execute format('drop policy if exists "Allow all insert on %I" on public.%I', tbl, tbl);
    execute format('create policy "Allow all insert on %I" on public.%I for insert with check (true)', tbl, tbl);

    execute format('drop policy if exists "Allow all update on %I" on public.%I', tbl, tbl);
    execute format('create policy "Allow all update on %I" on public.%I for update using (true)', tbl, tbl);

    execute format('drop policy if exists "Allow all delete on %I" on public.%I', tbl, tbl);
    execute format('create policy "Allow all delete on %I" on public.%I for delete using (true)', tbl, tbl);
  end loop;
end $$;

-- Add tables to supabase_realtime safely
do $$
declare
  tbl text;
begin
  foreach tbl in array array['profiles','posts','post_likes','post_comments','relationships','messages']
  loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = tbl
    ) then
      execute format('alter publication supabase_realtime add table public.%I', tbl);
    end if;
  end loop;
end $$;
